    Bug 2041478 - Introduce composeInlineSpellCheckEnabled setting for the messengerSettings API. r=aleca


    The setting is needed by the Grammar and Spell Checker add-on to become a pure WebExtension:
    https://addons.thunderbird.net/addon/grammar-and-spell-checker/

    Differential Revision: https://phabricator.services.mozilla.com/D301913

diff --git a/mail/components/extensions/parent/ext-messengerSettings.js b/mail/components/extensions/parent/ext-messengerSettings.js
index d80248eb283..95e5c9a3483 100644
--- a/mail/components/extensions/parent/ext-messengerSettings.js
+++ b/mail/components/extensions/parent/ext-messengerSettings.js
@@ -37,6 +37,17 @@ ExtensionPreferencesManager.addSetting("readerDisplayAttachmentsInline", {
   },
 });

+ExtensionPreferencesManager.addSetting("composeInlineSpellCheckEnabled", {
+  permission: "messengerSettings",
+  prefNames: ["mail.spellcheck.inline"],
+  setCallback(value) {
+    return { "mail.spellcheck.inline": !!value };
+  },
+  getCallback() {
+    return Services.prefs.getBoolPref("mail.spellcheck.inline");
+  },
+});
+
 this.messengerSettings = class extends ExtensionAPI {
   getAPI(context) {
     function makeSettingsAPI(options) {
@@ -54,6 +65,9 @@ this.messengerSettings = class extends ExtensionAPI {

     return {
       messengerSettings: {
+        composeInlineSpellCheckEnabled: makeSettingsAPI({
+          name: "composeInlineSpellCheckEnabled",
+        }),
         messageLineLengthLimit: makeSettingsAPI({
           name: "messageLineLengthLimit",
           readOnly: true,
